const aiItem = $input.first().json;
const webhookBody = $('Webhook').first().json.body || {};

// ------------------------------
// 1. Leer respuesta del AI Agent
// ------------------------------
let raw = aiItem.output || aiItem.text || aiItem.response || aiItem;

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let ai;

try {
  ai = JSON.parse(raw);
} catch (error) {
  ai = {
    intent: "desconocido",
    confidence: 0,
    entities: {},
    missing_fields: ["intent"],
    bot_response: "No pude interpretar bien tu mensaje. ¿Puedes escribirlo de otra forma?",
    should_append: false
  };
}

const entities = ai.entities || {};
const userMessage = webhookBody.chatInput || "";

// ------------------------------
// 2. Utilidades de normalización
// ------------------------------
function cleanText(value) {
  if (value === null || value === undefined) return "";

  return value
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanString(value) {
  if (value === null || value === undefined) return "";
  return value.toString().trim();
}

function pad2(value) {
  return value.toString().padStart(2, "0");
}

// ------------------------------
// 3. Normalizar fecha a YYYY-MM-DD cuando sea posible
// ------------------------------
function normalizeDate(value) {
  if (value === null || value === undefined || value === "") return "";

  const text = value.toString().trim();

  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }

  const numericValue = Number(text.replace(",", "."));
  if (!Number.isNaN(numericValue) && numericValue > 20000) {
    const wholeDays = Math.floor(numericValue);
    const base = Date.UTC(1899, 11, 30);
    const dateObj = new Date(base + wholeDays * 24 * 60 * 60 * 1000);
    return dateObj.toISOString().substring(0, 10);
  }

  const slashMatch = text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (slashMatch) {
    const day = pad2(slashMatch[1]);
    const month = pad2(slashMatch[2]);
    const year = slashMatch[3];
    return `${year}-${month}-${day}`;
  }

  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) {
    return parsed.toISOString().substring(0, 10);
  }

  return text.substring(0, 10);
}

// ------------------------------
// 4. Detectar canchas no existentes
// Solo existen fútbol 5 y fútbol 8.
// ------------------------------
function detectUnsupportedFieldNumbers(value, originalMessage) {
  const combined = `${cleanText(value)} ${cleanText(originalMessage)}`;
  const numbers = [];

  const regexPatterns = [
    /\bfutbol[\s_]*(\d{1,2})\b/g,
    /\bcancha\s*(?:de\s*)?(\d{1,2})\b/g
  ];

  for (const pattern of regexPatterns) {
    let match;
    while ((match = pattern.exec(combined)) !== null) {
      const number = Number(match[1]);
      if (!Number.isNaN(number)) numbers.push(number);
    }
  }

  const wordToNumber = {
    "uno": 1,
    "dos": 2,
    "tres": 3,
    "cuatro": 4,
    "cinco": 5,
    "seis": 6,
    "siete": 7,
    "ocho": 8,
    "nueve": 9,
    "diez": 10,
    "once": 11,
    "doce": 12
  };

  const wordPattern = /\b(?:futbol|cancha)(?:\s+de)?\s+(uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce)\b/g;
  let wordMatch;
  while ((wordMatch = wordPattern.exec(combined)) !== null) {
    const number = wordToNumber[wordMatch[1]];
    if (number) numbers.push(number);
  }

  const uniqueNumbers = [...new Set(numbers)];
  return uniqueNumbers.filter(number => number !== 5 && number !== 8);
}

// ------------------------------
// 5. Normalizar tipo de cancha
// ------------------------------
function normalizeFieldType(value, originalMessage) {
  const combined = `${cleanText(value)} ${cleanText(originalMessage)}`;

  if (
    combined.includes("futbol 5") ||
    combined.includes("futbol5") ||
    combined.includes("futbol_5") ||
    combined.includes("cancha de 5") ||
    combined.includes("cancha 5") ||
    combined.includes("futbol cinco") ||
    combined.includes("cancha de cinco") ||
    combined.includes("la pequena") ||
    combined.includes("pequena") ||
    combined.includes("sintetica pequena")
  ) {
    return "futbol_5";
  }

  if (
    combined.includes("futbol 8") ||
    combined.includes("futbol8") ||
    combined.includes("futbol_8") ||
    combined.includes("cancha de 8") ||
    combined.includes("cancha 8") ||
    combined.includes("futbol ocho") ||
    combined.includes("cancha de ocho") ||
    combined.includes("la mediana") ||
    combined.includes("mediana") ||
    combined.includes("la grande") ||
    combined.includes("grande") ||
    combined.includes("sintetica grande")
  ) {
    return "futbol_8";
  }

  return "";
}

// ------------------------------
// 6. Calcular precio
// ------------------------------
function calculatePrice(fieldType, durationMinutes) {
  const pricesPerHour = {
    futbol_5: 90000,
    futbol_8: 140000
  };

  const basePrice = pricesPerHour[fieldType] || 0;
  const duration = Number(durationMinutes) || 60;

  return Math.round(basePrice * (duration / 60));
}

// ------------------------------
// 7. Teléfono
// ------------------------------
function normalizePhone(value) {
  if (value === null || value === undefined) return "";

  const onlyDigits = value.toString().replace(/\D/g, "");
  const match = onlyDigits.match(/3\d{9}/);

  if (!match) return "";

  return match[0];
}

// ------------------------------
// 8. Extraer nombre como respaldo
// ------------------------------
function extractNameFallback(message) {
  if (!message) return "";

  const patterns = [
    /soy\s+([a-záéíóúñ\s]+?)(?:,|\.| mi celular| mi telefono| teléfono| telefono| quiero| y quiero| necesito| y necesito| con telefono| con teléfono)/i,
    /me llamo\s+([a-záéíóúñ\s]+?)(?:,|\.| mi celular| mi telefono| teléfono| telefono| quiero| y quiero| necesito| y necesito| con telefono| con teléfono)/i,
    /mi nombre es\s+([a-záéíóúñ\s]+?)(?:,|\.| mi celular| mi telefono| teléfono| telefono| quiero| y quiero| necesito| y necesito| con telefono| con teléfono)/i,
    /a nombre de\s+([a-záéíóúñ\s]+?)(?:,|\.| mi celular| mi telefono| teléfono| telefono| quiero| y quiero| necesito| y necesito| con telefono| con teléfono)/i
  ];

  for (const pattern of patterns) {
    const match = message.match(pattern);
    if (match && match[1]) {
      return match[1].replace(/\s+/g, " ").trim();
    }
  }

  return "";
}

// ------------------------------
// 9. Extraer ID de reserva si aparece
// ------------------------------
function extractReservationId(message) {
  if (!message) return "";

  const match = message.match(/R-\d{14,17}-?\d{0,3}/i);

  if (match) {
    return match[0].toUpperCase();
  }

  return "";
}

// ------------------------------
// 10. Convertir hora a minutos
// ------------------------------
function timeToMinutes(value) {
  if (value === null || value === undefined || value === "") return null;

  const textRaw = value.toString().trim().replace(",", ".");
  const numericValue = Number(textRaw);

  if (!Number.isNaN(numericValue)) {
    if (numericValue > 0 && numericValue < 1) return Math.round(numericValue * 24 * 60);
    if (numericValue >= 1 && numericValue < 24) return Math.round(numericValue * 60);
    if (numericValue >= 24) {
      const fraction = numericValue - Math.floor(numericValue);
      if (fraction > 0) return Math.round(fraction * 24 * 60);
      return null;
    }
  }

  let text = textRaw.toLowerCase();

  text = text
    .replace("p. m.", "pm")
    .replace("a. m.", "am")
    .replace("p.m.", "pm")
    .replace("a.m.", "am")
    .replace(/\s+/g, " ");

  const match = text.match(/^(\d{1,2})(?::(\d{1,2}))?(?::\d{1,2})?\s*(am|pm)?$/);

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridian = match[3] || "";

  if (Number.isNaN(hour) || Number.isNaN(minute)) return null;

  if (meridian === "pm" && hour < 12) hour += 12;
  if (meridian === "am" && hour === 12) hour = 0;

  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;

  return hour * 60 + minute;
}

function minutesToHHMM(minutes) {
  if (minutes === null || minutes === undefined) return "";
  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;
  return `${pad2(hour)}:${pad2(minute)}`;
}

// ------------------------------
// 11. Convertir fecha + hora de Colombia a milisegundos UTC
// Colombia no maneja horario de verano; UTC-5.
// ------------------------------
function bogotaDateTimeToUtcMillis(dateText, timeText) {
  const normalizedDate = normalizeDate(dateText);
  const minutes = timeToMinutes(timeText);

  if (!normalizedDate || minutes === null) return null;

  const match = normalizedDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;

  // Hora Colombia + 5 horas = UTC
  return Date.UTC(year, month - 1, day, hour + 5, minute, 0, 0);
}

function isDateTimeInPast(dateText, timeText) {
  const utcMillis = bogotaDateTimeToUtcMillis(dateText, timeText);
  if (utcMillis === null) return false;

  return utcMillis <= Date.now();
}

// ------------------------------
// 12. Validar horario de atención
// Horario permitido para agendar: 07:00 a 23:00.
// La reserva debe terminar máximo a las 23:00.
// ------------------------------
function validateBusinessHours(time, durationMinutes) {
  const OPEN_MINUTES = 7 * 60;
  const CLOSE_MINUTES = 23 * 60;

  if (!time) {
    return {
      valid: true,
      reason: ""
    };
  }

  const startMinutes = timeToMinutes(time);
  const duration = Number(durationMinutes) || 60;

  if (startMinutes === null) {
    return {
      valid: false,
      reason: "hora_invalida"
    };
  }

  const endMinutes = startMinutes + duration;

  if (startMinutes < OPEN_MINUTES || endMinutes > CLOSE_MINUTES) {
    return {
      valid: false,
      reason: "fuera_de_horario"
    };
  }

  return {
    valid: true,
    reason: ""
  };
}

// ------------------------------
// 13. Normalizar datos principales
// ------------------------------
const now = new Date();
const createdAt = now.toISOString();

const intent = cleanString(ai.intent || "desconocido");

const unsupportedFieldNumbers = detectUnsupportedFieldNumbers(
  entities.field_type,
  userMessage
);

const hasUnsupportedField = unsupportedFieldNumbers.length > 0;

let fieldType = normalizeFieldType(entities.field_type, userMessage);

if (hasUnsupportedField) {
  fieldType = "";
}

const date = normalizeDate(entities.date);
const rawTime = cleanString(entities.time);
const timeMinutes = timeToMinutes(rawTime);
const time = timeMinutes === null ? rawTime : minutesToHHMM(timeMinutes);
const duration = Number(entities.duration_minutes || 60);

const customerName =
  cleanString(entities.customer_name) ||
  cleanString(webhookBody.customerName) ||
  cleanString(webhookBody.customer_name) ||
  extractNameFallback(userMessage);

const phone =
  normalizePhone(entities.phone) ||
  normalizePhone(webhookBody.phone) ||
  normalizePhone(userMessage);

const reservationIdFromUser = extractReservationId(userMessage);
const priceCop = calculatePrice(fieldType, duration);

const businessHoursValidation = validateBusinessHours(time, duration);
const isOutsideBusinessHours = businessHoursValidation.valid === false;
const isPastReservation = Boolean(
  intent === "agendar_cancha" &&
  date &&
  time &&
  !isOutsideBusinessHours &&
  isDateTimeInPast(date, time)
);

// ------------------------------
// 14. Validación para agendar
// ------------------------------
const missingFields = [];

if (intent === "agendar_cancha") {
  if (!fieldType) missingFields.push("field_type");
  if (!date) missingFields.push("date");
  if (!time) missingFields.push("time");
  if (!customerName) missingFields.push("customer_name");
  if (!phone) missingFields.push("phone");
}

const invalidFields = [];

if (hasUnsupportedField) invalidFields.push("field_type");
if (isOutsideBusinessHours && intent === "agendar_cancha") invalidFields.push("time");
if (isPastReservation && intent === "agendar_cancha") invalidFields.push("date", "time");

const shouldAppend = Boolean(
  intent === "agendar_cancha" &&
  fieldType &&
  date &&
  time &&
  customerName &&
  phone &&
  missingFields.length === 0 &&
  invalidFields.length === 0
);

// ------------------------------
// 15. Validación para cancelar
// Para cancelar se puede usar:
// A) reservation_id
// o
// B) field_type + date + time + customer_name + phone
// ------------------------------
const missingCancelFields = [];
const hasReservationId = Boolean(reservationIdFromUser);

if (intent === "cancelar_reserva" && !hasReservationId) {
  if (!fieldType) missingCancelFields.push("field_type");
  if (!date) missingCancelFields.push("date");
  if (!time) missingCancelFields.push("time");
  if (!customerName) missingCancelFields.push("customer_name");
  if (!phone) missingCancelFields.push("phone");
}

const shouldCancel = Boolean(
  intent === "cancelar_reserva" &&
  !hasUnsupportedField &&
  (
    hasReservationId ||
    (
      fieldType &&
      date &&
      time &&
      customerName &&
      phone &&
      missingCancelFields.length === 0
    )
  )
);

// ------------------------------
// 16. Crear ID solo cuando se agenda
// ------------------------------
const newReservationId = shouldAppend
  ? "R-" + now.toISOString().replace(/\D/g, "").slice(0, 17) + "-" + Math.floor(Math.random() * 1000).toString().padStart(3, "0")
  : "";

// ------------------------------
// 17. Definir estado interno
// ------------------------------
let status = "no_aplica";

if (shouldAppend) {
  status = "pendiente_validacion";
} else if (shouldCancel) {
  status = "pendiente_cancelacion";
} else if (hasUnsupportedField) {
  status = "cancha_no_existente";
} else if (isOutsideBusinessHours && intent === "agendar_cancha") {
  status = "fuera_de_horario";
} else if (isPastReservation && intent === "agendar_cancha") {
  status = "reserva_en_pasado";
}

// ------------------------------
// 18. Respuesta previa
// ------------------------------
let botResponse = cleanString(ai.bot_response) || "Solicitud procesada.";

if (intent === "agendar_cancha" && hasUnsupportedField) {
  const requestedFieldsText = unsupportedFieldNumbers
    .map(number => `fútbol ${number}`)
    .join(", ");

  const missingWithoutFieldType = missingFields.filter(field => field !== "field_type");

  botResponse = `Por ahora solo tenemos canchas de fútbol 5 y fútbol 8. No puedo registrar reservas para ${requestedFieldsText}. Por favor indícame si deseas fútbol 5 o fútbol 8.`;

  if (isOutsideBusinessHours) {
    botResponse += ` Además, el horario disponible es de 7:00 a. m. a 11:00 p. m.; la reserva debe terminar máximo a las 23:00.`;
  }

  if (missingWithoutFieldType.length > 0) {
    botResponse += ` También me faltan estos datos: ${missingWithoutFieldType.join(", ")}.`;
  }
} else if (intent === "agendar_cancha" && isOutsideBusinessHours) {
  const missingWithoutTime = missingFields.filter(field => field !== "time");

  if (businessHoursValidation.reason === "hora_invalida") {
    botResponse = `La hora indicada no tiene un formato válido. Por favor escribe una hora dentro del horario de atención: de 7:00 a. m. a 11:00 p. m.`;
  } else {
    botResponse = `No puedo registrar la reserva a las ${time}. El horario disponible es de 7:00 a. m. a 11:00 p. m.; la reserva debe terminar máximo a las 23:00. Por favor intenta con otra hora dentro del horario.`;
  }

  if (missingWithoutTime.length > 0) {
    botResponse += ` Además, me faltan estos datos: ${missingWithoutTime.join(", ")}.`;
  }
} else if (intent === "agendar_cancha" && isPastReservation) {
  const missingWithoutDateTime = missingFields.filter(field => field !== "date" && field !== "time");

  botResponse = `No puedo registrar una reserva en una fecha u hora que ya pasó. Por favor escoge otra hora futura dentro del horario disponible de 7:00 a. m. a 11:00 p. m.`;

  if (missingWithoutDateTime.length > 0) {
    botResponse += ` Además, me faltan estos datos: ${missingWithoutDateTime.join(", ")}.`;
  }
} else if (intent === "agendar_cancha" && !shouldAppend) {
  botResponse = `Claro, puedo ayudarte a reservar. Me faltan estos datos: ${missingFields.join(", ")}.`;
}

if (shouldAppend) {
  botResponse = `Perfecto, ${customerName}. Voy a validar disponibilidad para ${fieldType} el ${date} a las ${time}.`;
}

if (intent === "cancelar_reserva" && hasUnsupportedField) {
  botResponse = `No puedo cancelar una reserva de esa cancha porque solo manejamos canchas de fútbol 5 y fútbol 8.`;
} else if (intent === "cancelar_reserva" && !shouldCancel) {
  botResponse = `Claro, puedo ayudarte a cancelar la reserva. Por favor indícame el ID de reserva o estos datos: tipo de cancha, fecha, hora, nombre y teléfono. Me faltan: ${missingCancelFields.join(", ")}.`;
}

if (shouldCancel) {
  botResponse = `Voy a buscar la reserva para verificar si se puede cancelar.`;
}

// ------------------------------
// 19. Salida hacia los siguientes nodos
// ------------------------------
return [
  {
    json: {
      reservation_id: shouldAppend ? newReservationId : reservationIdFromUser,
      session_id: webhookBody.sessionId || "cliente-web-001",
      customer_name: customerName,
      phone: phone,
      channel: "web",
      user_message: userMessage,
      intent: intent,
      field_type: fieldType,
      date: date,
      time: time,
      duration_minutes: duration,
      status: status,
      price_cop: priceCop,
      created_at: createdAt,
      notes: botResponse,
      bot_response: botResponse,
      should_append: Boolean(shouldAppend),
      should_cancel: Boolean(shouldCancel),
      missing_fields: missingFields,
      missing_cancel_fields: missingCancelFields,
      invalid_fields: invalidFields,
      unsupported_field_numbers: unsupportedFieldNumbers,
      is_past_reservation: Boolean(isPastReservation),
      business_hours: {
        open: "07:00",
        close: "23:00",
        valid: businessHoursValidation.valid,
        reason: businessHoursValidation.reason
      }
    }
  }
];

const nuevaReserva = $('PrepararFila').first().json;
const reservasExistentes = $input.all().map(item => item.json);

// ------------------------------
// 1. Normalizar texto
// ------------------------------
function normalize(value) {
  if (value === null || value === undefined) return "";

  return value
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function pad2(value) {
  return value.toString().padStart(2, "0");
}

// ------------------------------
// 2. Convertir fecha de Google Sheets o texto a YYYY-MM-DD
// ------------------------------
function normalizeDate(value) {
  if (value === null || value === undefined || value === "") return "";

  const text = value.toString().trim();

  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }

  const numericValue = Number(text.replace(",", "."));
  if (!Number.isNaN(numericValue) && numericValue > 20000) {
    const wholeDays = Math.floor(numericValue);
    const base = Date.UTC(1899, 11, 30);
    const date = new Date(base + wholeDays * 24 * 60 * 60 * 1000);
    return date.toISOString().substring(0, 10);
  }

  const slashMatch = text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (slashMatch) {
    const day = pad2(slashMatch[1]);
    const month = pad2(slashMatch[2]);
    const year = slashMatch[3];
    return `${year}-${month}-${day}`;
  }

  const parsed = new Date(text);
  if (!Number.isNaN(parsed.getTime())) {
    return parsed.toISOString().substring(0, 10);
  }

  return text.substring(0, 10);
}

// ------------------------------
// 3. Convertir hora a minutos
// ------------------------------
function toMinutes(value) {
  if (value === null || value === undefined || value === "") return null;

  const textRaw = value.toString().trim().replace(",", ".");
  const numericValue = Number(textRaw);

  if (!Number.isNaN(numericValue)) {
    if (numericValue > 0 && numericValue < 1) return Math.round(numericValue * 24 * 60);
    if (numericValue >= 1 && numericValue < 24) return Math.round(numericValue * 60);
    if (numericValue >= 24) {
      const fraction = numericValue - Math.floor(numericValue);
      if (fraction > 0) return Math.round(fraction * 24 * 60);
      return null;
    }
  }

  let text = textRaw.toLowerCase();

  text = text
    .replace("p. m.", "pm")
    .replace("a. m.", "am")
    .replace("p.m.", "pm")
    .replace("a.m.", "am")
    .replace(/\s+/g, " ");

  const match = text.match(/^(\d{1,2})(?::(\d{1,2}))?(?::\d{1,2})?\s*(am|pm)?$/);

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridian = match[3] || "";

  if (Number.isNaN(hour) || Number.isNaN(minute)) return null;

  if (meridian === "pm" && hour < 12) hour += 12;
  if (meridian === "am" && hour === 12) hour = 0;

  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;

  return hour * 60 + minute;
}

function bogotaDateTimeToUtcMillis(dateText, timeText) {
  const normalizedDate = normalizeDate(dateText);
  const minutes = toMinutes(timeText);

  if (!normalizedDate || minutes === null) return null;

  const match = normalizedDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;

  return Date.UTC(year, month - 1, day, hour + 5, minute, 0, 0);
}

// ------------------------------
// 4. Datos de la nueva reserva
// ------------------------------
const nuevaCancha = normalize(nuevaReserva.field_type);
const nuevaFecha = normalizeDate(nuevaReserva.date);
const nuevaInicio = toMinutes(nuevaReserva.time);
const nuevaDuracion = Number(nuevaReserva.duration_minutes || 60);
const nuevaFin = nuevaInicio === null ? null : nuevaInicio + nuevaDuracion;

// Seguridad: no guardar reservas en el pasado aunque el nodo anterior falle.
const nuevaReservaUtc = bogotaDateTimeToUtcMillis(nuevaReserva.date, nuevaReserva.time);
if (nuevaReservaUtc !== null && nuevaReservaUtc <= Date.now()) {
  const mensajePasado = "No puedo registrar una reserva en una fecha u hora que ya pasó. Por favor escoge otra hora futura dentro del horario disponible.";
  return [
    {
      json: {
        ...nuevaReserva,
        should_append: false,
        is_available: false,
        sheet_updated: false,
        status: "reserva_en_pasado",
        bot_response: mensajePasado,
        notes: mensajePasado
      }
    }
  ];
}

// Seguridad: si algo llega mal, no guardar.
if (!nuevaCancha || !nuevaFecha || nuevaInicio === null) {
  const mensajeError = "No pude validar la disponibilidad porque faltan datos de cancha, fecha u hora. Por favor revisa la solicitud.";

  return [
    {
      json: {
        ...nuevaReserva,
        should_append: false,
        is_available: false,
