function normalizeDate(value) {
  if (value === null || value === undefined || value === "") return "";

  const text = value.toString().trim();

  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }

  const numericValue = Number(text.replace(",", "."));
  if (!Number.isNaN(numericValue) && numericValue > 20000) {
    const wholeDays = Math.floor(numericValue);
    const base = Date.UTC(1899, 11, 30);
    const dateObj = new Date(base + wholeDays * 24 * 60 * 60 * 1000);
    return dateObj.toISOString().substring(0, 10);
  }

  const slashMatch = text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (slashMatch) {
    const day = pad2(slashMatch[1]);
    const month = pad2(slashMatch[2]);
    const year = slashMatch[3];
    return `${year}-${month}-${day}`;
  }

  const dateObj = new Date(text);
  if (!Number.isNaN(dateObj.getTime())) {
    return dateObj.toISOString().substring(0, 10);
  }

  return text.substring(0, 10);
}

function toMinutes(value) {
  if (value === null || value === undefined || value === "") return null;

  const textRaw = value.toString().trim().replace(",", ".");
  const numericValue = Number(textRaw);

  if (!Number.isNaN(numericValue)) {
    if (numericValue > 0 && numericValue < 1) return Math.round(numericValue * 24 * 60);
    if (numericValue >= 1 && numericValue < 24) return Math.round(numericValue * 60);
    if (numericValue >= 24) {
      const fraction = numericValue - Math.floor(numericValue);
      if (fraction > 0) return Math.round(fraction * 24 * 60);
      return null;
    }
  }

  let text = textRaw.toLowerCase();

  text = text
    .replace("p. m.", "pm")
    .replace("a. m.", "am")
    .replace("p.m.", "pm")
    .replace("a.m.", "am")
    .replace(/\s+/g, " ");

  const match = text.match(/^(\d{1,2})(?::(\d{1,2}))?(?::\d{1,2})?\s*(am|pm)?$/);

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridian = match[3] || "";

  if (Number.isNaN(hour) || Number.isNaN(minute)) return null;

  if (meridian === "pm" && hour < 12) hour += 12;
  if (meridian === "am" && hour === 12) hour = 0;

  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;

  return hour * 60 + minute;
}

function bogotaDateTimeToUtcMillis(dateText, timeText) {
  const normalizedDate = normalizeDate(dateText);
  const minutes = toMinutes(timeText);

  if (!normalizedDate || minutes === null) return null;

  const match = normalizedDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;

  // Hora Colombia + 5 horas = UTC
  return Date.UTC(year, month - 1, day, hour + 5, minute, 0, 0);
}

