  const meridian = match[3] || "";

  if (meridian === "pm" && hour < 12) hour += 12;
  if (meridian === "am" && hour === 12) hour = 0;

  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return hour * 60 + minute;
}

function formatTime(value) {
  const minutes = toMinutes(value);
  if (minutes === null) return value || "";
  const hour = Math.floor(minutes / 60);
  const minute = minutes % 60;
  return `${pad2(hour)}:${pad2(minute)}`;
}

function fieldLabel(value) {
  const normalized = normalize(value);
  if (normalized === "futbol_5" || normalized === "futbol 5") return "fútbol 5";
  if (normalized === "futbol_8" || normalized === "futbol 8") return "fútbol 8";
  return value || "cancha no especificada";
}

function money(value) {
  const number = Number(value || 0);
  if (!number) return "";
  return `$${number.toLocaleString("es-CO")} COP`;
}

function rowTimestamp(row) {
  const created = Date.parse(row.created_at || "");
  if (!Number.isNaN(created)) return created;

  const date = normalizeDate(row.date);
  const minutes = toMinutes(row.time);
  if (date && minutes !== null) {
    const [year, month, day] = date.split("-").map(Number);
    const hour = Math.floor(minutes / 60);
    const minute = minutes % 60;
    return Date.UTC(year, month - 1, day, hour + 5, minute, 0, 0);
  }

  return row.__index || 0;
}

// Primero buscamos reservas de la misma sesión.
// Esto evita responder con reservas de otro usuario.
const sameSession = reservas.filter(row => normalize(row.session_id) === normalize(sessionId));

// Priorizamos reservas confirmadas. Si no hay confirmadas, mostramos la última relacionada con esa sesión.
const confirmed = sameSession.filter(row => normalize(row.status) === "confirmada");
const candidates = confirmed.length > 0
  ? confirmed
  : sameSession.filter(row => normalize(row.status) !== "");

if (candidates.length === 0) {
  return [
    {
      json: {
        reply: "Todavía no encuentro una reserva asociada a esta conversación. Puedes hacer una reserva indicando tipo de cancha, fecha, hora, nombre y teléfono.",
        intent: "consultar_memoria_reserva",
        sheet_updated: false,
        available: null,
        status: "sin_memoria_reserva",
        field_type: "",
        date: "",
        time: "",
        reservation_id: ""
      }
    }
  ];
}

const latest = candidates
  .map(row => ({ row, timestamp: rowTimestamp(row) }))
  .sort((a, b) => b.timestamp - a.timestamp)[0].row;

const status = normalize(latest.status);
const fecha = normalizeDate(latest.date);
const hora = formatTime(latest.time);
const cancha = fieldLabel(latest.field_type);
const valor = money(latest.price_cop);
const id = latest.reservation_id || "";
const nombre = latest.customer_name || "el nombre registrado";

let reply;

if (status === "confirmada") {
  reply = `Tu última reserva confirmada es para cancha de ${cancha}, el ${fecha} a las ${hora}, a nombre de ${nombre}.`;
  if (valor) reply += ` Valor: ${valor}.`;
  if (id) reply += ` ID de reserva: ${id}.`;
} else if (status === "cancelada") {
  reply = `La última reserva asociada a esta conversación aparece cancelada. Era para cancha de ${cancha}, el ${fecha} a las ${hora}, a nombre de ${nombre}.`;
  if (id) reply += ` ID de reserva: ${id}.`;
} else {
  reply = `La última reserva asociada a esta conversación está en estado "${latest.status}". Cancha: ${cancha}, fecha: ${fecha}, hora: ${hora}.`;
  if (id) reply += ` ID de reserva: ${id}.`;
}

return [
  {
    json: {
      reply,
      intent: "consultar_memoria_reserva",
      sheet_updated: false,
      available: null,
      status: status || "memoria_reserva",
      field_type: latest.field_type || "",
      date: fecha,
      time: hora,
      reservation_id: id,
      customer_name: latest.customer_name || "",
      phone: latest.phone || "",
      price_cop: latest.price_cop || "",
      source: "google_sheets_memoria",
      session_id: sessionId
    }
  }
];
